import { LogicWrapper, MakeLogicType, actions, afterMount, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingExternalReferencesSearchIssuesRetrieve } from '../generated/api'
import { ErrorTrackingExternalIssueResultApi } from '../generated/api.schemas'

export interface ExternalIssueSearchLogicProps {
    integrationId: number
    requiresRepository: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface externalIssueSearchLogicValues {
    repository: string
    results: ErrorTrackingExternalIssueResultApi[]
    resultsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface externalIssueSearchLogicActions {
    inputChanged: (query: string) => {
        query: string
    }
    issueSelected: () => {
        value: true
    }
    searchIssues: (query: any) => any
    searchIssuesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    searchIssuesSuccess: (
        results: ErrorTrackingExternalIssueResultApi[],
        payload?: any
    ) => {
        results: ErrorTrackingExternalIssueResultApi[]
        payload?: any
    }
    setRepository: (repository: string) => {
        repository: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface externalIssueSearchLogicMeta {
    key: number
}

export type externalIssueSearchLogicType = MakeLogicType<
    externalIssueSearchLogicValues,
    externalIssueSearchLogicActions,
    ExternalIssueSearchLogicProps,
    externalIssueSearchLogicMeta
>

export const externalIssueSearchLogic: LogicWrapper<externalIssueSearchLogicType> = kea<externalIssueSearchLogicType>([
    props({} as ExternalIssueSearchLogicProps),
    key((props) => props.integrationId),
    path((key) => ['products', 'error_tracking', 'components', 'externalIssueSearchLogic', key]),
    actions({
        setRepository: (repository: string) => ({ repository }),
        inputChanged: (query: string) => ({ query }),
        issueSelected: true,
    }),
    loaders(({ props, values, cache }) => ({
        results: [
            [] as ErrorTrackingExternalIssueResultApi[],
            {
                searchIssues: async (query, breakpoint) => {
                    const search = query.trim()
                    if (search) {
                        // A nonblank search cancels any pending selection-clear search at the
                        // breakpoint below, so its suppression must not survive to swallow a
                        // later genuine clear.
                        cache.suppressNextBlankSearch = false
                    }
                    if (props.requiresRepository && !values.repository) {
                        return values.results
                    }
                    // The breakpoint debounces typing and cancels superseded searches, so a slow
                    // response can never overwrite the results of a newer query.
                    await breakpoint(300)
                    // Selecting an option makes LemonInputSelect clear its input, which is
                    // indistinguishable from the user clearing the search. The clear can land
                    // before issueSelected (option click) or after it (input blur), so the flag
                    // is only reliable here, after the debounce, not at dispatch time.
                    if (!search && cache.suppressNextBlankSearch) {
                        cache.suppressNextBlankSearch = false
                        return values.results
                    }
                    const response = await errorTrackingExternalReferencesSearchIssuesRetrieve(
                        String(teamLogic.values.currentTeamId),
                        {
                            integration_id: props.integrationId,
                            search,
                            repository: props.requiresRepository ? values.repository : undefined,
                        }
                    )
                    breakpoint()
                    return response.issues
                },
            },
        ],
    })),
    reducers({
        repository: [
            '',
            {
                setRepository: (_, { repository }) => repository,
            },
        ],
        results: {
            // Stale options must not stay selectable while a new search is pending.
            searchIssues: (state, query) => (typeof query === 'string' && query.trim() ? [] : state),
            setRepository: () => [],
        },
    }),
    listeners(({ actions, cache }) => ({
        setRepository: () => {
            // A repository change clears the results, so the reload must not be suppressed.
            cache.suppressNextBlankSearch = false
            actions.searchIssues('')
        },
        issueSelected: () => {
            cache.suppressNextBlankSearch = true
        },
        inputChanged: ({ query }) => actions.searchIssues(query),
    })),
    afterMount(({ actions }) => {
        actions.searchIssues('')
    }),
])
